do $$ declare d text; begin select pg_get_functiondef(p.oid) into d from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='map_network_nearby_v1' limit 1; if d is null then raise exception 'map_network_nearby_v1 not found'; end if; d := replace(d, 'and (p_category is null or coalesce(p.category,l.place_type)=p_category)', 'and (p_category is null or lower(p_category)=''all'' or lower(coalesce(p.category,l.place_type,''''))=lower(p_category) or (lower(p_category)=''restroom'' and (lower(coalesce(l.bathroom_verification_status,'''')) in (''has_bathroom'',''verified'') or lower(coalesce(l.place_type,'''')) in (''restroom'',''bathroom'',''toilet'') or lower(coalesce(p.category,'''')) in (''restroom'',''bathroom'',''toilet'') or lower(coalesce(l.source_metadata->>''amenity'','''')) in (''toilets'',''restroom'',''bathroom'') or lower(coalesce(l.source_metadata->>''toilets'','''')) in (''yes'',''public'',''customers'') or lower(coalesce(l.source_metadata->>''restroom'','''')) in (''yes'',''public'',''customers'') or lower(coalesce(l.source_metadata->>''bathroom'','''')) in (''yes'',''public'',''customers'') or coalesce((l.source_metadata->''osm_tags''->>''amenity''),'''') ilike ''toilet%'')))'); d := replace(d, 'coalesce(r.p_category,r.place_type,''service'')', 'case when lower(coalesce(p_category,''''))=''restroom'' then ''restroom'' else coalesce(r.p_category,r.place_type,''service'') end'); execute d; end $$;
